CREATE TABLE public.audit_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), mode text NOT NULL CHECK (mode IN ('definitions','endpoint','transcript')), source text NOT NULL, endpoint text, fingerprint text NOT NULL, tools jsonb NOT NULL DEFAULT '[]', inventory jsonb NOT NULL, signals jsonb NOT NULL, verdict jsonb NOT NULL, reports jsonb NOT NULL, model text NOT NULL);
GRANT SELECT ON public.audit_records TO authenticated;
GRANT ALL ON public.audit_records TO service_role;
ALTER TABLE public.audit_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_owner_read ON public.audit_records FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE INDEX audit_records_owner_time ON public.audit_records(user_id, created_at DESC);
CREATE TABLE public.tool_approvals (audit_id uuid PRIMARY KEY REFERENCES public.audit_records(id), user_id uuid NOT NULL, tools text[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tool_approvals TO authenticated;
GRANT ALL ON public.tool_approvals TO service_role;
ALTER TABLE public.tool_approvals ENABLE ROW LEVEL SECURITY;
CREATE POLICY approval_owner_read ON public.tool_approvals FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.enforcement_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, audit_id uuid NOT NULL REFERENCES public.audit_records(id), created_at timestamptz NOT NULL DEFAULT now(), tool text NOT NULL, decision text NOT NULL CHECK (decision IN ('blocked','forwarded','failed')), reason text NOT NULL);
GRANT SELECT ON public.enforcement_events TO authenticated;
GRANT ALL ON public.enforcement_events TO service_role;
ALTER TABLE public.enforcement_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_owner_read ON public.enforcement_events FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.audit_usage (user_id uuid NOT NULL, bucket bigint NOT NULL, count integer NOT NULL DEFAULT 1, PRIMARY KEY(user_id,bucket));
GRANT ALL ON public.audit_usage TO service_role;
ALTER TABLE public.audit_usage ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_audit_quota(p_user uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; BEGIN INSERT INTO public.audit_usage(user_id,bucket) VALUES(p_user,floor(extract(epoch from now()) / 60)::bigint) ON CONFLICT(user_id,bucket) DO UPDATE SET count = audit_usage.count + 1 RETURNING count INTO n; RETURN n <= 3; END; $$;
REVOKE ALL ON FUNCTION public.consume_audit_quota(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_audit_quota(uuid) TO service_role;